<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\EscrowStatus;
use App\Enums\OrderStatus;
use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\Relations\HasOne;
use Illuminate\Support\Carbon;

/**
 * @property OrderStatus $status
 * @property EscrowStatus $escrow_status
 */
/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $number
 * @property string $buyer_id
 * @property string $seller_id
 * @property OrderStatus $status
 * @property OrderStatus|null $status_before_hold
 * @property EscrowStatus $escrow_status
 * @property EscrowStatus|null $escrow_status_before_hold
 * @property string $kind
 * @property string|null $offer_id
 * @property string|null $swap_request_id
 * @property string|null $promo_code_id
 * @property string $currency
 * @property int $items_amount
 * @property int $freight_amount
 * @property int $buyer_protection_amount
 * @property int|null $duties_amount
 * @property int $discount_amount
 * @property int $swap_fee_amount
 * @property int $cash_adjustment_amount
 * @property int $total_amount
 * @property int $platform_fee_bps
 * @property int $platform_fee_amount
 * @property int $seller_net_amount
 * @property int $refunded_amount
 * @property array|null $shipping_address
 * @property array|null $shipping_option
 * @property string|null $carrier
 * @property string|null $tracking_number
 * @property string|null $tracking_url
 * @property array|null $route
 * @property Carbon|null $estimated_delivery_from
 * @property Carbon|null $estimated_delivery_to
 * @property string $risk
 * @property array|null $risk_signals
 * @property string|null $hold_reason
 * @property Carbon|null $reserved_until
 * @property Carbon|null $paid_at
 * @property Carbon|null $dispatch_due_at
 * @property Carbon|null $dispatched_at
 * @property Carbon|null $delivered_at
 * @property Carbon|null $auto_release_at
 * @property Carbon|null $dispute_window_ends_at
 * @property Carbon|null $completed_at
 * @property Carbon|null $funds_available_at
 * @property Carbon|null $funds_settled_at
 * @property Carbon|null $delivered_reminder_sent_at
 * @property Carbon|null $cancelled_at
 * @property string|null $cancellation_reason
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Order extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'ord';

    protected $fillable = [
        'number', 'buyer_id', 'seller_id', 'kind', 'offer_id', 'swap_request_id', 'promo_code_id', 'currency',
        'items_amount', 'freight_amount', 'buyer_protection_amount', 'duties_amount', 'discount_amount',
        'swap_fee_amount', 'cash_adjustment_amount', 'total_amount', 'platform_fee_bps', 'platform_fee_amount',
        'seller_net_amount', 'shipping_address', 'shipping_option', 'risk', 'risk_signals', 'reserved_until',
        'estimated_delivery_from', 'estimated_delivery_to', 'route',
    ];

    protected $attributes = ['status' => 'pending_payment', 'escrow_status' => 'not_funded', 'kind' => 'purchase'];

    protected function casts(): array
    {
        return [
            'status' => OrderStatus::class,
            'status_before_hold' => OrderStatus::class,
            'escrow_status' => EscrowStatus::class,
            'escrow_status_before_hold' => EscrowStatus::class,
            'shipping_address' => 'array',
            'shipping_option' => 'array',
            'route' => 'array',
            'risk_signals' => 'array',
            'items_amount' => 'integer',
            'freight_amount' => 'integer',
            'buyer_protection_amount' => 'integer',
            'duties_amount' => 'integer',
            'discount_amount' => 'integer',
            'swap_fee_amount' => 'integer',
            'cash_adjustment_amount' => 'integer',
            'total_amount' => 'integer',
            'platform_fee_amount' => 'integer',
            'seller_net_amount' => 'integer',
            'refunded_amount' => 'integer',
            'reserved_until' => 'datetime',
            'paid_at' => 'datetime',
            'dispatch_due_at' => 'datetime',
            'dispatched_at' => 'datetime',
            'delivered_at' => 'datetime',
            'auto_release_at' => 'datetime',
            'dispute_window_ends_at' => 'datetime',
            'completed_at' => 'datetime',
            'funds_available_at' => 'datetime',
            'funds_settled_at' => 'datetime',
            'delivered_reminder_sent_at' => 'datetime',
            'cancelled_at' => 'datetime',
            'estimated_delivery_from' => 'datetime',
            'estimated_delivery_to' => 'datetime',
        ];
    }

    // ---------------------------------------------------------------- relations

    /** @return BelongsTo<User, $this> */
    public function buyer(): BelongsTo
    {
        return $this->belongsTo(User::class, 'buyer_id');
    }

    /** @return BelongsTo<User, $this> */
    public function seller(): BelongsTo
    {
        return $this->belongsTo(User::class, 'seller_id');
    }

    /** @return HasMany<OrderItem, $this> */
    public function items(): HasMany
    {
        return $this->hasMany(OrderItem::class);
    }

    /** @return HasMany<OrderEvent, $this> */
    public function events(): HasMany
    {
        return $this->hasMany(OrderEvent::class)->orderBy('occurred_at');
    }

    /** @return HasMany<Payment, $this> */
    public function payments(): HasMany
    {
        return $this->hasMany(Payment::class, 'payable_id')->where('payable_type', 'order');
    }

    /** @return HasOne<Payment, $this> */
    public function successfulPayment(): HasOne
    {
        return $this->hasOne(Payment::class, 'payable_id')->where('payable_type', 'order')
            ->whereIn('status', ['successful', 'partially_refunded', 'refunded'])->latestOfMany();
    }

    /** @return HasOne<Payment, $this> */
    public function latestPayment(): HasOne
    {
        return $this->hasOne(Payment::class, 'payable_id')->where('payable_type', 'order')->latestOfMany();
    }

    /** @return HasMany<Refund, $this> */
    public function refunds(): HasMany
    {
        return $this->hasMany(Refund::class);
    }

    /** @return BelongsTo<Offer, $this> */
    public function offer(): BelongsTo
    {
        return $this->belongsTo(Offer::class);
    }

    /** @return BelongsTo<SwapRequest, $this> */
    public function swapRequest(): BelongsTo
    {
        return $this->belongsTo(SwapRequest::class);
    }

    /** @return BelongsTo<PromoCode, $this> */
    public function promoCode(): BelongsTo
    {
        return $this->belongsTo(PromoCode::class);
    }

    /** @return HasMany<Dispute, $this> */
    public function disputes(): HasMany
    {
        return $this->hasMany(Dispute::class);
    }

    /** @return HasMany<Review, $this> */
    public function reviews(): HasMany
    {
        return $this->hasMany(Review::class);
    }

    // ---------------------------------------------------------------- money

    public function money(int $amount): Money
    {
        return Money::of($amount, $this->currency);
    }

    public function total(): Money
    {
        return $this->money($this->total_amount);
    }

    /** Amount still held for the seller after refunds. */
    public function escrowedAmount(): Money
    {
        return $this->money($this->total_amount - $this->refunded_amount);
    }

    // ---------------------------------------------------------------- parties

    public function isBuyer(User $user): bool
    {
        return $user->id === $this->buyer_id;
    }

    public function isSeller(User $user): bool
    {
        return $user->id === $this->seller_id;
    }

    public function isParty(User $user): bool
    {
        return $this->isBuyer($user) || $this->isSeller($user);
    }

    public function requiresShipping(): bool
    {
        return $this->shipping_option !== null;
    }
}
